//! 🧪️ Final selection preserves neutral ordered semantics and exact observed physical ownership.
use super::*;
use crate::{OperationMessageDrain, MutationReplayOutcome};
use semio_framework_trace::observe_heap_allocations_on_this_thread;
fn level(number: u64) -> Severity { [Severity::Info, Severity::Warning, Severity::Error, Severity::Fatal][number as usize] }
fn observed(work: impl FnOnce() -> Result<RetainedCloneProgress,ValueError>, grant: RetainedCloneGrant) -> RetainedCloneProgress { let(result,heap)=observe_heap_allocations_on_this_thread(work);let progress=result.unwrap();assert!(progress.fits(grant));assert!(progress.copied_bytes+progress.retained_capacity_bytes<=4096);assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes));progress }
fn outcome(messages:Vec<MutationMessage>)->MutationReplayOutcome {MutationReplayOutcome {mutation_id:crate::MutationId("original".into()),edit_id:"edit".into(),op_index:0,worst:None,messages,superseded:false,withdrawn:false}}
fn accumulate(messages:Vec<MutationMessage>)->ReplayMessageAccumulator {let mut ledger=ReplayMessageAccumulator::default();let mut cursor=OperationMessageDrain::new(outcome(messages));for _ in 0..100000 {if cursor.is_finished(){drop(cursor.take());return ledger;}let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:cursor.next_copy_byte_demand(&ledger),maximum_capacity_bytes:cursor.next_capacity_byte_demand(&ledger).unwrap(),maximum_release_bytes:cursor.next_release_byte_demand(),maximum_depth:64};observed(||cursor.step(&mut ledger,grant),grant);}panic!("original rows did not transfer");}
fn close(ledger:&mut ReplayMessageAccumulator){for _ in 0..100000{if ledger.terminal_is_empty(){return;}let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:ledger.next_close_copy_byte_demand(),maximum_capacity_bytes:0,maximum_release_bytes:ledger.next_close_release_byte_demand().unwrap(),maximum_depth:64};observed(||ledger.close_step(grant),grant);}panic!("paged row closure did not terminate");}
fn close_cursor(cursor:&mut FinalMessageSelection){cursor.begin_close();for _ in 0..100000{if cursor.terminal_is_empty(){return;}let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:cursor.next_close_copy_byte_demand(),maximum_capacity_bytes:0,maximum_release_bytes:cursor.next_close_release_byte_demand(),maximum_depth:1};let short=RetainedCloneGrant {maximum_release_bytes:grant.maximum_release_bytes.saturating_sub(1),..grant};if short!=grant{assert_eq!(observed(||Ok(cursor.close_step(short)),short),Default::default());}observed(||Ok(cursor.close_step(grant)),grant);}panic!("final selection closure did not terminate");}
fn select(mut ledger:ReplayMessageAccumulator,edit:&str,cancel:Option<usize>)->Option<Vec<MutationMessage>>{
 let((mut cursor,()),heap)=observe_heap_allocations_on_this_thread(||(FinalMessageSelection::new(edit.len(),ledger.rows().len()),()));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(size_of::<FinalMessageSelection>()<=4096);
 for turn in 0..100000 {if cancel==Some(turn){close_cursor(&mut cursor);close(&mut ledger);let(_,heap)=observe_heap_allocations_on_this_thread(||drop((cursor,ledger)));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));println!("[DEBUG] final paged selection exact partial retirement turn={turn}");return None;}if cursor.is_finished(){assert!(ledger.terminal_is_empty());let rows=cursor.take().unwrap();let(_,heap)=observe_heap_allocations_on_this_thread(||drop((cursor,ledger)));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));return Some(rows);}let((copy,capacity,release),heap)=observe_heap_allocations_on_this_thread(||(cursor.next_copy_byte_demand(&ledger),cursor.next_capacity_byte_demand(),cursor.next_release_byte_demand(&ledger).unwrap()));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:capacity,maximum_release_bytes:release,maximum_depth:1};assert!(copy+capacity<=4096);for short in [RetainedCloneGrant::default(),RetainedCloneGrant {maximum_depth:0,..grant},RetainedCloneGrant {maximum_copy_bytes:copy.saturating_sub(1),..grant},RetainedCloneGrant {maximum_capacity_bytes:capacity.saturating_sub(1),..grant},RetainedCloneGrant {maximum_release_bytes:release.saturating_sub(1),..grant}]{if short!=grant{assert_eq!(observed(||cursor.step(&mut ledger,short),short),Default::default());}}observed(||cursor.step(&mut ledger,grant),grant);}
 panic!("single final selection did not finish");
}
#[test]
fn final_message_selection_native_original_counts_utf8_targets_and_exact_cancellation(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();
 for case in law["cases"].as_array().unwrap(){let make=||case["rows"].as_array().unwrap().iter().enumerate().map(|(index,row)|{let mut message=MutationMessage::fatal("mutation.invariant",row["text"].as_str().unwrap().repeat(row["repeat"].as_u64().unwrap()as usize));message.level=level(row["level"].as_u64().unwrap());message.target=row["targets"].as_array().unwrap().iter().map(|target|target.as_str().unwrap().to_string()).collect();message.op_index=Some(index as u32);message}).collect::<Vec<_>>();let originals=make();let mut ledger=ReplayMessageAccumulator::default();for mut row in originals {let mut pending=Some(row);while pending.is_some(){let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:if ledger.rows().has_reserved_slot(){size_of::<MutationMessage>()}else{0},maximum_capacity_bytes:ledger.next_capacity_byte_demand().unwrap(),maximum_release_bytes:0,maximum_depth:1};observed(||ledger.append(&mut pending,grant),grant);}}let rows=select(ledger,case["editId"].as_str().unwrap(),None).unwrap();let kept:Vec<_>=rows.iter().filter(|row|row.code.0!="mutation.cascade").map(|row|row.op_index.unwrap()as usize).collect();assert_eq!(serde_json::to_value(kept).unwrap(),case["expectedKept"]);let dropped=case["dropped"].as_u64().unwrap();if dropped>0{let summary=rows.last().unwrap();assert_eq!(summary.code.0,"mutation.cascade");assert_eq!(summary.message,format!("{dropped} more messages"));let worst=&rows[0];assert!(worst.target.is_empty());assert!(std::str::from_utf8(worst.message.as_bytes()).is_ok());}assert!(rows.len()<=42);let bytes=rows.iter().fold(case["editId"].as_str().unwrap().len(),|bytes,row|bytes+MUTATION_MESSAGE_OWNER_BYTES+row.code.0.len()+row.message.len()+row.target.iter().map(|target|MUTATION_MESSAGE_TARGET_BYTES+target.len()).sum::<usize>());assert!(bytes<=4096);let mut returned=accumulate(rows);close(&mut returned);println!("[DEBUG] one final original-row selection case={} dropped={dropped} exactbytes={bytes} UTF8/emptytarget normativeparity",case["name"]);
 for cancel in law["cancelAt"].as_array().unwrap(){if let Some(rows)=select(accumulate(make()),case["editId"].as_str().unwrap(),Some(cancel.as_u64().unwrap()as usize)){let mut returned=accumulate(rows);close(&mut returned);}}
 }
 let original:serde_json::Value=serde_json::from_str(include_str!("../../📦️accumulate/🧫️fixtures/🔣️.json")).unwrap();for case in original["cases"].as_array().unwrap(){let mut messages=Vec::new();for group in case["operations"].as_array().unwrap(){for _ in 0..group["count"].as_u64().unwrap(){let mut row=MutationMessage::fatal("mutation.invariant",group["text"].as_str().unwrap().repeat(group["bytes"].as_u64().unwrap()as usize));row.level=match group["level"].as_str().unwrap(){"fatal"=>Severity::Fatal,"error"=>Severity::Error,"warning"=>Severity::Warning,_=>Severity::Info};row.op_index=Some(messages.len()as u32);messages.push(row);}}let mut ledger=ReplayMessageAccumulator::default();for row in messages{let mut pending=Some(row);while pending.is_some(){let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:if ledger.rows().has_reserved_slot(){size_of::<MutationMessage>()}else{0},maximum_capacity_bytes:ledger.next_capacity_byte_demand().unwrap(),maximum_release_bytes:0,maximum_depth:1};observed(||ledger.append(&mut pending,grant),grant);}}let rows=select(ledger,case["editId"].as_str().unwrap(),None).unwrap();assert_eq!(serde_json::to_value(rows.iter().filter(|row|row.code.0!="mutation.cascade").map(|row|row.op_index.unwrap()as usize).collect::<Vec<_>>()).unwrap(),case["expectedKept"]);assert_eq!(rows.last().unwrap().message,format!("{} more messages",case["expectedDropped"]));let mut ledger=accumulate(rows);close(&mut ledger);println!("[DEBUG] full original omission count and stable severity prefix {}",case["name"]);}
}
